     3	import hotel.messages.EmailSender;
     4	import hotel.messages.SentMessages;
     5	import hotel.reports.OccupancyReport;
     6	import hotel.reports.RevenueReport;
     7	import hotel.reservations.PriceCalculator;
     8	import hotel.reservations.ReservationService;
     9	import hotel.reservations.ReservationStore;
    10	import hotel.rooms.Rooms;
    11	import hotel.web.HttpApi;
    12	import io.javalin.Javalin;
    13	import javax.sql.DataSource;
    14	
    15	/** Puts the inn's pieces together and runs the HTTP server. */
    16	public final class Hotel {
    17	
    18	    private final Javalin server;
    19	
    20	    public Hotel(DataSource dataSource) {
    21	        Rooms rooms = new Rooms(dataSource);
    22	        ReservationStore store = new ReservationStore(dataSource);
    23	        SentMessages sentMessages = new SentMessages(dataSource);
    24	        ReservationService reservations =
    25	                new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(sentMessages));
    26	        HttpApi api = new HttpApi(
    27	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
    28	        this.server = api.server();
    29	    }
    30	
    31	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
    32	    public int start(int port) {
    33	        server.start(port);
    34	        return server.port();
    35	    }
    36	
    37	    public void stop() {
    38	        server.stop();
    39	    }
    40	
    41	    public static void main(String[] args) {
    42	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
    43	        Database database = new Database(System.getenv());
    44	        new Hotel(database.dataSource()).start(port);
    45	    }
    46	}
=== src/main/java/hotel/reservations/ReservationService.java
     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.documents.TextFormat;
     5	import hotel.messages.EmailSender;
     6	import hotel.rooms.Room;
     7	import hotel.rooms.Rooms;
     8	import java.math.BigDecimal;
     9	
    10	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    11	public final class ReservationService {
    12	
    13	    static final String HOTEL_NAME = "Pousada Maré Alta";
    14	    static final String HOUSEKEEPING_EMAIL = "governanca@pousadamarealta.com.br";
    15	    static final String FINANCE_EMAIL = "financeiro@pousadamarealta.com.br";
    16	
    17	    private final Rooms rooms;
    18	    private final ReservationStore store;
    19	    private final PriceCalculator priceCalculator;
    20	    private final EmailSender emailSender;
    21	
    22	    public ReservationService(
    23	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    24	        this.rooms = rooms;
    25	        this.store = store;
    26	        this.priceCalculator = priceCalculator;
    27	        this.emailSender = emailSender;
    28	    }
    29	
    30	    public synchronized Reservation create(NewReservation request) {
    31	        if (!request.checkOut().isAfter(request.checkIn())) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    33	        }
    34	        if (request.guests() < 1) {
    35	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    36	        }
    37	        Room room = rooms.find(request.roomNumber())
    38	                .orElseThrow(() -> new HotelException(
    39	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    40	        if (request.guests() > room.capacity()) {
    41	            throw new HotelException(
    42	                    ErrorCode.CAPACITY_EXCEEDED,
    43	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    44	        }
    45	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    46	            throw new HotelException(
    47	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    48	        }
    49	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    50	        return store.add(request, price);
    51	    }
    52	
    53	    public Reservation find(long reservationId) {
    54	        return store.find(reservationId)
    55	                .orElseThrow(() -> new HotelException(
    56	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    57	    }
    58	
    59	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    60	    public synchronized Reservation confirm(long reservationId) {
    61	        Reservation reservation = find(reservationId);
    62	        if (reservation.status() != ReservationStatus.PENDING) {
    63	            throw notAllowed(reservation, "confirm");
    64	        }
    65	        reservation.confirmPayment();
    66	        store.update(reservation);
    67	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    68	        emailSender.send(
    69	                reservation.guest().email(),
    70	                "Reserva confirmada - " + HOTEL_NAME,
    71	                confirmationEmailBody(reservation, receipt));
    72	        Room room = roomOf(reservation);
    73	        emailSender.send(HOUSEKEEPING_EMAIL, "Reserva confirmada - quarto " + room.number(),
    74	                "Quarto " + room.number() + " (" + room.type() + ")\n"
    75	                + "Entrada: " + TextFormat.date(reservation.checkIn())
    76	                + " | Saída: " + TextFormat.date(reservation.checkOut()) + "\n"
    77	                + "Hóspedes: " + reservation.guests() + "\n");
    78	        emailSender.send(FINANCE_EMAIL, "Pagamento recebido - reserva " + reservation.id(),
    79	                "Reserva " + reservation.id() + " (" + reservation.guest().name() + "): pagamento de "
    80	                        + TextFormat.money(reservation.amountPaid()) + ".\n");
    81	        return reservation;
    82	    }
    83	
    84	    /**
    85	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    86	     * reservation was never paid, so nothing comes back).
    87	     */
    88	    public synchronized Reservation cancel(long reservationId) {
    89	        Reservation reservation = find(reservationId);
    90	        if (reservation.status() != ReservationStatus.PENDING
    91	                && reservation.status() != ReservationStatus.CONFIRMED) {
    92	            throw notAllowed(reservation, "cancel");
    93	        }
    94	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    95	        BigDecimal refund = switch (reservation.ratePlan()) {
    96	            case STANDARD -> reservation.amountPaid();
    97	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    98	        };
    99	        reservation.cancel(refund);
   100	        store.update(reservation);
   101	        if (wasConfirmed) {
   102	            int roomNumber = reservation.roomNumber();
   103	            emailSender.send(HOUSEKEEPING_EMAIL, "Reserva cancelada - quarto " + roomNumber,
   104	                    "O quarto " + roomNumber + " ficou livre de " + TextFormat.date(reservation.checkIn())
   105	                            + " a " + TextFormat.date(reservation.checkOut()) + ".\n");
   106	            if (refund.signum() > 0) {
   107	                emailSender.send(FINANCE_EMAIL, "Reembolso - reserva " + reservation.id(),
   108	                        "Devolver " + TextFormat.money(refund) + " para " + reservation.guest().name() + ".\n");
   109	            }
   110	        }
   111	        return reservation;
   112	    }
   113	
   114	    public synchronized Reservation checkIn(long reservationId) {
   115	        Reservation reservation = find(reservationId);
   116	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   117	            throw notAllowed(reservation, "check in");
   118	        }
   119	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   120	        store.update(reservation);
   121	        return reservation;
   122	    }
   123	
   124	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   125	    public synchronized ReservationReceipt checkOut(long reservationId) {
   126	        Reservation reservation = find(reservationId);
   127	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   128	            throw notAllowed(reservation, "check out");
   129	        }
   130	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   131	        store.update(reservation);
   132	        return new ReservationReceipt(reservation, roomOf(reservation));
   133	    }
   134	
   135	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   136	    public ReservationReceipt receiptCopy(long reservationId) {
   137	        Reservation reservation = find(reservationId);
   138	        if (!reservation.isPaid()) {
   139	            throw notAllowed(reservation, "issue a receipt for");
   140	        }
   141	        return new ReservationReceipt(reservation, roomOf(reservation));
   142	    }
   143	
   144	    private Room roomOf(Reservation reservation) {
   145	        return rooms.find(reservation.roomNumber()).orElseThrow();
   146	    }
   147	
   148	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   149	        return "Olá, " + reservation.guest().name() + "!\n\n"
   150	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   151	                + receipt.text() + "\n"
   152	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   153	                + "Até breve!\n";
   154	    }
   155	
   156	    private static HotelException notAllowed(Reservation reservation, String operation) {
   157	        return new HotelException(
   158	                ErrorCode.OPERATION_NOT_ALLOWED,
   159	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   160	    }
   161	}
=== src/main/java/hotel/reservations/ReservationStore.java
     1	package hotel.reservations;
     2	
     3	import java.math.BigDecimal;
     4	import java.sql.Connection;
     5	import java.sql.Date;
     6	import java.sql.PreparedStatement;
     7	import java.sql.ResultSet;
     8	import java.sql.SQLException;
     9	import java.time.LocalDate;
    10	import java.util.ArrayList;
    11	import java.util.List;
    12	import java.util.Optional;
    13	import javax.sql.DataSource;
    14	
    15	/** Keeps the reservations in the database. */
    16	public final class ReservationStore {
    17	
    18	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    19	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
    20	    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
    21	    private static final String EXCLUSION_VIOLATION = "23P01";
    22	
    23	    private final DataSource dataSource;
    24	
    25	    public ReservationStore(DataSource dataSource) {
    26	        this.dataSource = dataSource;
    27	    }
    28	
    29	    /** Saves a new reservation; the database numbers it. */
    30	    Reservation add(NewReservation request, Price price) {
    31	        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
    32	                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) "
    33	                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
    34	        try (Connection connection = dataSource.getConnection();
    35	                PreparedStatement statement = connection.prepareStatement(insert)) {
    36	            statement.setInt(1, request.roomNumber());
    37	            statement.setString(2, request.guest().name());
    38	            statement.setString(3, request.guest().email());
    39	            statement.setString(4, request.guest().cpf());
    40	            statement.setDate(5, Date.valueOf(request.checkIn()));
    41	            statement.setDate(6, Date.valueOf(request.checkOut()));
    42	            statement.setInt(7, request.guests());
    43	            statement.setString(8, request.ratePlan().name());
    44	            statement.setInt(9, price.nights());
    45	            statement.setBigDecimal(10, price.subtotal());
    46	            statement.setBigDecimal(11, price.discount());
    47	            statement.setBigDecimal(12, price.total());
    48	            statement.setString(13, ReservationStatus.PENDING.name());
    49	            statement.setBigDecimal(14, PriceCalculator.cents(BigDecimal.ZERO));
    50	            try (ResultSet generated = statement.executeQuery()) {
    51	                generated.next();
    52	                return new Reservation(generated.getLong("id"), request, price);
    53	            }
    54	        } catch (SQLException failure) {
    55	            if (EXCLUSION_VIOLATION.equals(failure.getSQLState())) {
    56	                throw new HotelException(ErrorCode.ROOM_UNAVAILABLE,
    57	                        "room " + request.roomNumber() + " is taken on some of those nights");
    58	            }
    59	            throw new IllegalStateException("could not save the reservation", failure);
    60	        }
    61	    }
    62	
    63	    /** Saves what changes in a reservation's life: the status, what was paid and what went back. */
    64	    void update(Reservation reservation) {
    65	        try (Connection connection = dataSource.getConnection();
    66	                PreparedStatement statement = connection.prepareStatement(
    67	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    68	            statement.setString(1, reservation.status().name());
    69	            statement.setBigDecimal(2, reservation.amountPaid());
    70	            statement.setBigDecimal(3, reservation.refund());
    71	            statement.setLong(4, reservation.id());
    72	            statement.executeUpdate();
    73	        } catch (SQLException failure) {
    74	            throw new IllegalStateException("could not save reservation " + reservation.id(), failure);
    75	        }
    76	    }
    77	
    78	    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
    79	    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
    80	        try (Connection connection = dataSource.getConnection();
    81	                PreparedStatement select = connection.prepareStatement(
    82	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    83	                                + "AND check_in < ? AND ? < check_out")) {
    84	            select.setInt(1, roomNumber);
    85	            select.setDate(2, Date.valueOf(checkOut));
    86	            select.setDate(3, Date.valueOf(checkIn));
    87	            try (ResultSet rows = select.executeQuery()) {
    88	                return rows.next();
    89	            }
    90	        } catch (SQLException failure) {
    91	            throw new IllegalStateException("could not check room " + roomNumber, failure);
    92	        }
    93	    }
    94	
    95	    public Optional<Reservation> find(long id) {
    96	        try (Connection connection = dataSource.getConnection();
    97	                PreparedStatement select = connection.prepareStatement(
    98	                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
    99	            select.setLong(1, id);
   100	            try (ResultSet rows = select.executeQuery()) {
   101	                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
   102	            }
   103	        } catch (SQLException failure) {
   104	            throw new IllegalStateException("could not read reservation " + id, failure);
   105	        }
   106	    }
   107	
   108	    public List<Reservation> all() {
   109	        try (Connection connection = dataSource.getConnection();
   110	                PreparedStatement select = connection.prepareStatement(
   111	                        "SELECT " + COLUMNS + " FROM reservations ORDER BY id");
   112	                ResultSet rows = select.executeQuery()) {
   113	            List<Reservation> reservations = new ArrayList<>();
   114	            while (rows.next()) {
   115	                reservations.add(read(rows));
   116	            }
   117	            return reservations;
   118	        } catch (SQLException failure) {
   119	            throw new IllegalStateException("could not read the reservations", failure);
   120	        }
   121	    }
   122	
   123	    private static Reservation read(ResultSet row) throws SQLException {
   124	        Guest guest = new Guest(row.getString("guest_name"), row.getString("guest_email"), row.getString("guest_cpf"));
   125	        NewReservation request = new NewReservation(
   126	                row.getInt("room_number"),
   127	                guest,
   128	                row.getDate("check_in").toLocalDate(),
   129	                row.getDate("check_out").toLocalDate(),
   130	                row.getInt("guests"),
   131	                RatePlan.valueOf(row.getString("rate_plan")));
   132	        Price price = new Price(
   133	                row.getInt("nights"), row.getBigDecimal("subtotal"), row.getBigDecimal("discount"),
   134	                row.getBigDecimal("total"));
   135	        return new Reservation(
   136	                row.getLong("id"),
   137	                request,
   138	                price,
   139	                ReservationStatus.valueOf(row.getString("status")),
   140	                row.getBigDecimal("amount_paid"),
   141	                row.getBigDecimal("refund"));
   142	    }
   143	}
