360	     3	import hotel.rooms.Room;
361	     4	import java.math.BigDecimal;
362	     5	import java.math.RoundingMode;
363	     6	import java.time.LocalDate;
364	     7	import java.time.Month;
365	     8	
366	     9	/**
367	    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
368	    11	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
369	    12	 * (half-even) at every step.
370	    13	 */
371	    14	public final class PriceCalculator {
372	    15	
373	    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
374	    17	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
375	    18	
376	    19	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
377	    20	        int nights = 0;
378	    21	        BigDecimal subtotal = cents(BigDecimal.ZERO);
379	    22	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
380	    23	            subtotal = subtotal.add(nightPrice(room, night));
381	    24	            nights++;
382	    25	        }
383	    26	        BigDecimal discount = switch (ratePlan) {
384	    27	            case STANDARD -> cents(BigDecimal.ZERO);
385	    28	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
386	    29	        };
387	    30	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
388	    31	    }
389	    32	
390	    33	    BigDecimal nightPrice(Room room, LocalDate night) {
391	    34	        BigDecimal nightlyRate = room.nightlyRate();
392	    35	        if (isHighSeason(night)) {
393	    36	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
394	    37	        }
395	    38	        return cents(nightlyRate);
396	    39	    }
397	    40	
398	    41	    /** High season: from December 15 to the end of February, and the whole of July. */
399	    42	    static boolean isHighSeason(LocalDate date) {
400	    43	        Month month = date.getMonth();
401	    44	        return month == Month.JANUARY
402	    45	                || month == Month.FEBRUARY
403	    46	                || month == Month.JULY
404	    47	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
405	    48	    }
406	    49	
407	    50	    static BigDecimal cents(BigDecimal value) {
408	    51	        return value.setScale(2, RoundingMode.HALF_EVEN);
409	    52	    }
410	    53	}
