518	    26	            boolean coversNight = !reservation.checkIn().isAfter(night) && reservation.checkOut().isAfter(night);
519	    27	            if (reservation.isPaid() && coversNight) {
520	    28	                occupying.add(reservation);
521	    29	            }
522	    30	        }
523	    31	        occupying.sort(Comparator.comparingInt(Reservation::roomNumber));
524	    32	
