526	    34	        csv.append("room,type,reservation,check_in,check_out\n");
527	    35	        for (Reservation reservation : occupying) {
528	    36	            Room room = rooms.find(reservation.roomNumber()).orElseThrow();
529	    37	            csv.append(room.number()).append(',')
530	    38	                    .append(room.type()).append(',')
