576	    37	        for (Reservation reservation : withRevenue) {
577	    38	            csv.append(reservation.id()).append(',')
578	    39	                    .append(reservation.roomNumber()).append(',')
579	    40	                    .append(reservation.checkIn()).append(',')
580	    41	                    .append(reservation.checkOut()).append(',')
